const root=load("sql_receiver_authority").receiver_root,imgs=load("sql_custody_native_receipt").files.filter(f=>f.binary_original);
const calls=await Promise.allSettled(imgs.map(f=>tools.mcp__codex_apps__remote_desktop_commander_read_file({deviceId:"0b4ac27b-8500-47d0-8f11-5a35402e9abc",path:root+"/"+f.path})));
const t=new Function(load("nmr_transport_helper"))(),h=new Function(load("nmr_binary_hash_helper"))(),out=[];
for(let i=0;i<calls.length;i++){
 if(calls[i].status!=="fulfilled")throw calls[i].reason;
 const response=calls[i].value,block=response.content?.find(x=>x.type==="image");if(!block)throw Error("Original PNG image block missing "+imgs[i].path);
 const bytes=t.from64(block.data);if(bytes.length!==imgs[i].bytes||h.sha256(bytes)!==imgs[i].sha256)throw Error("Original PNG transport differs "+imgs[i].path);
 out.push({file:imgs[i],request:{deviceId:"0b4ac27b-8500-47d0-8f11-5a35402e9abc",path:root+"/"+imgs[i].path},response,image:block,base64:block.data});
 text({path:imgs[i].path,bytes:imgs[i].bytes,sha256:imgs[i].sha256,git_blob:imgs[i].git_blob,exact_native_bytes:true});
 image(block,"original");
}
store("sql_actual_original_png_reads",out);
